import os

# Search more broadly for task files
search_paths = [
    "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/play/users/u026/system/state/workspace/",
    "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/play/",
    "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/seen-reference-3/",
]

# Find all task files
for root_path in search_paths:
    print(f"\nSearching in {root_path}")
    if os.path.exists(root_path):
        for f in sorted(os.listdir(root_path)):
            if f.startswith("task-"):
                fpath = os.path.join(root_path, f)
                print(f"  Found: {fpath}")

# Also search in home
print("\n=== Searching home ===")
for f in sorted(os.listdir('/home/USER')):
    fpath = os.path.join('/home/USER', f)
    if os.path.exists(fpath) and os.path.isdir(fpath):
        for f2 in sorted(os.listdir(fpath)):
            if f2.startswith("task-"):
                print(f"  Found: /home/USER/{f}/{f2}")

# Try a different approach - search the entire runs directory for task files
import os

paths_to_check = [
    "/home/USER/runs/paper",
]

found_files = []
for root, dirs, files in os.walk("/home/USER"):
    # Skip too deep
    depth = root.count(os.sep)
    if depth > 10:
        continue
    for f in files:
        if f.endswith(".py") or f.endswith(".json"):
            full_path = os.path.join(root, f)
            # Get relative path from runs
            rel = os.path.relpath(full_path, "/home/USER/runs")
            if "task" in rel.lower():
                found_files.append(rel)

print(f"Found {len(found_files)} task-related files:")
for f in sorted(found_files)[:20]:
    print(f"  {f}")

