# More systematic analysis of Demo 1
# Key observation: Only 4s connected to 1s SOMEHOW change

# Demo 1 complete grid analysis
rows = 16
cols = 27

# 1s positions
ones = set()
# row 0 cols 19-25
for c in range(19, 26):
    ones.add((0, c))
# col 17 rows 1-6
for r in range(1, 7):
    ones.add((r, 17))
# col 22 rows 10-11
for r in range(10, 12):
    ones.add((r, 22))

# 4s positions  
fours = set()
# row 9 cols 13-15, cols 21-23
for c in range(13, 16):
    fours.add((9, c))
for c in range(21, 24):
    fours.add((9, c))
# col 13 rows 6-9
for r in range(6, 10):
    fours.add((r, 13))
# col 21 rows 6-11
for r in range(6, 12):
    fours.add((r, 21))
# col 22 rows 9-11
for r in range(9, 12):
    fours.add((r, 22))

print(f"Total 4-cells: {len(fours)}")
print(f"Total 1-cells: {len(ones)}")

# Actual changes (confirmed)
changing = {(9,14),(9,15),(9,21),(9,22),(10,22),(11,22)}

# Check for each 4-cell: does it share row/col with a 1?
def shares_row_with_1(pos):
    r, c = pos
    return any(r == r1 and c1 in c_set for r1, c1 in ((0, i) for i in range(19, 27)) for c1 in [(c) for (_r, _c) in ones if _r==0])
def shares_col_with_1(pos):
    r, c = pos
    return any(c == c1 and r1 in r_set for r1, c1 in ((i, 17) for i in range(1, 8)) for r1 in [(r) for (_r, _c) in ones if _c==17])

def any_all_1s_in_row(row, ones):
    for r1, c1 in ones:
        if r1 == row:
            return True
    return False

def any_all_1s_in_col(col, ones):
    for r1, c1 in ones:
        if c1 == col:
            return True
    return False

# Let me build a VISUAL representation of which cells are "connected"
