# Compute distance from each changed 4 to nearest 1 in Demo 2
from math import sqrt

def manhattan_dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def min_dist_to_ones(pos, ones):
    r, c = pos
    mind = float('inf')
    minpos = None
    for r1, c1 in ones:
        d = manhattan_dist((r,c), (r1,c1))
        if d < mind:
            mind = d
            minpos = (r1, c1)
    return mind, minpos

